ANNOTATIONS = [
    (1, 'before', 'Meta yoga（flexbox 引擎）的纯 TypeScript 移植，替代上游 WASM 包——Ink 是终端 UI，一次布局要跑上千节点，跨 JS/WASM 边界的调用开销比算法本身还大，所以整份重写成 JS'),
    (40, 'before', '上面三档特性分得很清楚：Ink 真正用到的、为规范一致性而实现但不用的、明确不实现的——把「为什么有这段死代码」写在文件头，是这类移植件最省事的维护手段'),
    (41, 'before', '只从同目录 enums 取枚举，没有第三方依赖——移植件的价值就在于零依赖可内联打包'),
    (60, 'before', '原样 re-export 全部枚举，让调用方只 import 这一个文件就能拿到 yoga-layout/load 的完整类型面'),
    (82, 'before', 'Value 是所有长度/边距/位置的统一表示：一个单位标记加一个数值，没有用 undefined 表示缺失，而是用 Unit.Undefined 这个枚举值'),
    (87, 'before', '两个共享哨兵：未定义与 auto 的 value 都是 NaN——用单位标记区分语义，数值位永远是脏的，任何忘了先看 unit 就读 value 的代码都会拿到 NaN 并立刻暴露'),
    (90, 'after_block', '裸对象每次返回新实例，但 Value 是不可变的语义值，共享是安全的；注意 UNDEFINED_VALUE 被 defaultStyle 里 new Array(9).fill() 共享了 9 次，所以任何地方都不能原地改 Value'),
    (97, 'before', 'resolveValue 是全文件唯一的「值到像素」求值点：Point 直接返回，Percent 乘 ownerSize，其余一律 NaN——NaN 在这里是「无法解析」的通用信号，靠 isDefined 判断'),
    (108, 'before', 'isDefined 就是 !isNaN；全文件用 NaN 而不是 null/undefined 表示「尺寸不定」，因为 NaN 能穿过所有算术运算而不抛错，布局里到处都是加减法'),
    (113, 'before', 'NaN 安全的相等：a === b 或两者都是 NaN。缓存比对必须用这个而不是 ===，否则未定义尺寸的节点永远缓存不命中，等于白做缓存'),
    (120, 'before', 'Layout 是输出侧：物理边数组固定四元组顺序 left/top/right/bottom，不做 9 边模型——9 边只在输入 Style 里存在，一次解析后就塌缩掉'),
    (134, 'before', 'Style 是输入侧：margin/padding/border/position 都是 9 槽数组按 Edge 枚举索引，gap 是 3 槽——保留 yoga 的原始形状，是为了让 setter 能直接写下标，不用翻译'),
    (167, 'before', '默认值逐条对齐 CSS flexbox 与 yoga 初值：主轴 column（不是 CSS 的 row）、align-items stretch、flex-shrink 0（CSS 是 1，yoga 特别注明这是与 Web 默认的差异）'),
    (182, 'after_block', '四组边数组各自 fill 同一个 UNDEFINED_VALUE 引用，gap 只有 3 槽；靠共享对象省掉 9×4 次分配，代价是 Value 必须当不可变值用'),
    (199, 'before', '四个物理边常量用 0..3 编号，是为了能直接当 Layout 里四元组的下标；Edge 枚举的 9 个逻辑值在 setter 阶段写入，到这里全部翻译完'),
    (204, 'before', 'resolveEdge 是 9 边塌缩到 1 个像素值的唯一正确实现，回退链有四层：具体边 → 水平/垂直 → all → start/end 映射。顺序错了就会让 marginHorizontal 盖掉 marginLeft'),
    (223, 'after_block', 'start/end 在 LTR 下等价于 left/right；Ink 恒传 Direction.LTR，所以这里省掉了方向判断，注释里明写了这个前提'),
    (229, 'after', 'auto 对 margin/position 返回 NaN（交给调用方做特殊分配），对 padding/border 返回 0——同一个 auto 在内边距上是无意义的，静默归零而不是报错'),
    (233, 'before', 'resolveEdgeRaw 只跑回退链不解析百分比，返回 Value 本身。它的唯一用途是判断「这条边是不是 auto」，因为 auto 一旦解析成 NaN 就丢了来源信息'),
    (256, 'before', '两个快速判定直接写字面量 3 和 0 而不是 Unit.Auto/Unit.Undefined——这是 CPU 剖析后确认的热点，枚举属性访问在 V8 里比数字比较慢'),
    (269, 'before', 'resolveEdges4Into：把 resolveEdge 调 4 次的共享回退查表（Horizontal/Vertical/All/Start/End）提到循环外，并写进调用方预分配的数组——原版每次调用会新建一个 4 元组，1000 节点基准上就是 4000 次分配'),
    (287, 'after', '每个边都是同一串三目：Point 取值、Percent 乘百分比分母、其余归零。故意写成表达式而不是语句，让 V8 保持单态内联'),
    (312, 'before', '轴向助手：isRow 判主轴是否水平、isReverse 判是否反向、crossAxis 把 row 映射成 column。全文件从不直接比较 flexDirection 字面量，一律过这三个函数'),
    (321, 'before', 'leadingEdge/trailingEdge 把逻辑主轴方向翻译成物理边编号；四个 case 全覆盖且没有 default，靠 TS 的穷尽性检查保证新增方向时编译报错'),
    (349, 'before', 'MeasureFunction 是文本节点向布局引擎报尺寸的唯一通道：布局引擎给约束（宽/高与各自模式），回调返回实际内容尺寸。Ink 的 Text 组件就是挂这个函数'),
    (374, 'before', 'createConfig 里一半方法是空实现：实验特性恒 false、free 不做事——这些 API 存在只为让从 WASM 迁过来的代码不用改'),
    (403, 'before', 'Node 是唯一的可变实体，yoga 的 C++ 版本背后是原生指针，这里就是一个普通对象；外部拿到的是这个对象本身而不是句柄，所以 free 只能做语义上的清理'),
    (413, 'before', '以下 _ 前缀字段全是布局过程的暂存，不属于公开 API：flex-basis、主轴/交叉尺寸、行号，加上一整套缓存'),
    (418, 'before', '快速路径标志位：CPU 剖析显示定位循环对每个子节点每趟要调 isMarginAuto 6 次、resolveEdgeRaw(position) 4 次，1000 节点基准约 1.1 万次，而绝大多数节点既没有 auto margin 也没有 position 内缩值——用一个布尔的代价跳过这 10 次调用'),
    (426, 'after_block', '同一套思路用在三个边数组上：1000 节点基准里约 67% 的 resolveEdges4Into 调用操作的是全 undefined 数组（只有列有 padding、只有叶子有 margin），单分支跳过胜过 20 次读属性加 15 次比较加 4 次写零'),
    (434, 'before', '单槽布局缓存，镜像上游 CalculateLayout.cpp 的 layoutNodeInternal：子树干净且问的是同一个问题就直接返回。为什么是两个槽而不是一个——每个节点通常会先收到一次 measure 调用（performLayout=false，来自 computeFlexBasis）再收到一次 layout 调用，单槽会互相踩踏'),
    (450, 'before', '_hasL 在计算之前就写入输入，但 layout.width/height 会被多槽缓存和后续不同输入的调用改写；如果只存输入不存输出，命中时会返回上一次调用残留的尺寸——这就是 scrollbox 视口高度从 33 变成 2624、滚动条归零、屏幕全黑的那个 bug'),
    (467, 'before', 'flex-basis 缓存：干净子节点的 basis 只取决于容器的内框尺寸，没变就跳过整趟 layoutNode(performLayout=false) 递归。滚动场景的热路径是：500 条消息的容器脏了，499 个干净子节点会被脏链的测量/布局级联各测约 20 次，缓存直接在子节点边界短路'),
    (479, 'before', '_fbGen 用代际号而不是 isDirty_ 当闸门：脏节点的缓存是上一次布局留下的（子树已经变了）所以必须废掉，但同一个代际内缓存是新的——虚拟滚动新挂载的项第一趟就脏，脏链一次布局里会调它 2 的深度次方次，而子树在这期间根本没变'),
    (487, 'before', '多槽缓存存「输入 → 算出的宽高」：上游 yoga 用 16 槽，这里 4 槽就覆盖 Ink 的脏链深度。用扁平 Float64Array 存，避免每条目一个对象；槽 i 在 _cIn 里占 [i*8, i*8+8)，在 _cOut 里占 [i*2, i*2+2)'),
    (498, 'before', '构造器只做初值填充，不触发任何布局；config 缺省时共用模块级 DEFAULT_CONFIG，所以「没传 config」的节点在配置上完全等价'),
    (515, 'before', '存活计数在这里递增、在 free 里递减，供基准测试检测泄漏——移植件没有原生析构，只能靠这对计数加手工断引用'),
    (520, 'before', 'insertChild 用 splice 支持任意位置插入，而不是只 append——Ink 的兄弟顺序就是渲染顺序，插到中间是常态'),
    (545, 'before', 'free 做的是断引用加清缓存，没有真正释放内存；注释里那个 _yogaLiveNodes-- 在重复调用时会减两次，但调用方约定只 free 一次，所以没加防护'),
    (557, 'before', 'reset 把节点还原成出厂状态并逐个清空全部缓存槽——新增缓存字段时最容易漏改这里，漏一个就会出现「复用节点带着上次的尺寸」'),
    (577, 'before', 'markDirty 只在上行父节点尚未标记时才递归，所以脏链上溯是 O(链长) 而不是 O(树)；代价是重复标记同一子树是幂等的，不会重复上溯'),
    (584, 'before', 'hasNewLayout 恒 true、markLayoutSeen 空实现——这两个 API 是 yoga 给增量渲染用的，Ink 每帧全量读，直接退化掉'),
    (591, 'before', '换 measure 函数必须标脏：文本内容变了但节点结构没变，唯一的变化信号就是这里'),
    (614, 'before', 'ComputedRight/Bottom 不是存下来的，而是用父节点宽高减去自身 left 加 width 反推——所以父节点尺寸变了、子节点位置没变时，这两个值会自动跟着变，不需要重算'),
    (651, 'before', '每个尺寸属性都有三态 setter：数值/字符串（含百分比）、单独的 Percent 版本、单独的 Auto 版本。这样调用方不用拼字符串，也免得每次都走 parseDimension 的正则分支'),
    (722, 'before', 'setFlex 是 CSS flex 简写的语义压缩：负数表示只设 shrink（grow 归零），正数表示 grow 加 shrink=1 加 basis=0（CSS 的 flex: N），未定义全归零。这段是 flexbox 规范里最容易被写错的一处'),
    (788, 'before', 'setPosition 每次重算 _hasPosition 而不是简单地置 true——因为可以把某条边设回 undefined，此时必须能重新变回 false，否则快速路径会一直走慢支'),
    (811, 'before', '三个空实现：box-sizing 只支持 border-box、aspect-ratio 完全不支持、copyStyle 没人调用。写成空方法而不是删掉，是为了让 API 面与上游一致'),
    (817, 'before', 'setMargin 是三个 setter 里唯一要维护两个标志的：_hasAutoMargin（供 auto margin 分配用）与 _hasMargin（供边解析快速路径用），而且要处理「把 auto 改回普通值」的情况'),
    (853, 'before', 'gap 只有 3 个槽：row、column、all。主轴方向取哪个槽由 flex-direction 决定，所以 resolveGap 的调用方要传 Gutter.Column 或 Gutter.Row'),
    (907, 'before', '这一整段 API 桩只为接口对齐存在：赋值函数体全空、取值函数返回 NaN 或恒定值——从 WASM 版本迁过来的调用方不会因为缺方法而崩'),
    (927, 'before', 'calculateLayout 是唯一入口：重置计数器并递增代际号，然后用「根节点没有被谁约束」的语义（Undefined 模式、可用尺寸等于自身）启动递归'),
    (948, 'after_block', '根节点即使没有父容器也要吃自己的 margin 与 position 内缩值——yoga 在根上也应用定位，因为根节点的绝对 left/top 是像素网格遍历的起点，漏掉会让整棵树差半个像素'),
    (962, 'before', '递归算完后统一做像素网格舍入：pointScaleFactor 为 0 时直接返回（表示不做舍入）。这一步必须在整棵树的尺寸都定下来之后做，否则会累积误差'),
    (968, 'before', '多槽缓存的槽数。取 4 而不是上游的 16：Ink 的脏链深度很少超过 4，槽多了反而抬高每次扫描比较的成本'),
    (969, 'before', 'cacheWrite 把这次调用的输入与实际算出的宽高存进环形槽位；输入共 8 个字段（可用宽高、两个模式、owner 宽高、两个 force 标志），输出 2 个'),
    (985, 'before', '脏节点跨代首次写入时先清空旧槽：上一代留下的条目对应的是改动前的子树，尺寸已经失效。干净节点的旧条目则保留——子树没变，同样输入必得同样结果，这正是滚动热路径能跨代命中的原因'),
    (995, 'before', '写指针环绕但 _cN 保持在满值：读的时候总要扫全部已填充的槽，不能只扫本轮写过的几个，否则环绕之后老条目永远读不到'),
    (1022, 'before', 'commitCacheOutputs 把算完的宽高写进单槽缓存的输出字段。输入在 layoutNode 开头就提交了（那时还没算），输出必须在这里才提交——这个先后顺序错了就会出现读回上一次残留尺寸的问题'),
    (1035, 'before', '四个模块级计数器，每次 calculateLayout 开头清零，供基准测试与调试读取。它们让「这个文件到底快了多少」变成可测量的，而不是靠感觉'),
    (1044, 'before', 'getYogaCounters 是这组计数器唯一的出口；live 不是本趟的统计量而是全局存活节点数，语义上和其他三个不同，放在同一个返回值里是为了少一次导出'),
    (1058, 'before', 'layoutNode 是整个引擎的心脏：给定可用尺寸与两个测量模式，算出这个节点的宽高、可选地把子节点逐个定位，并维护三层缓存。参数里 forceWidth/forceHeight 表示「忽略自身样式尺寸」——父容器做主轴的伸缩分配后已经定了尺寸，不能再让子节点的 width 覆盖'),
    (1072, 'after', '访问计数每进一次就加一，不管后面是否命中缓存；它和 cacheHits 一起看才能判断缓存是否真的减少了递归'),
    (1076, 'before', '三级缓存查找，优先级从高到低：单槽 layout 缓存、多槽缓存、单槽 measure 缓存。整体跳过条件是「节点干净」或「同代际的 measure 调用」'),
    (1086, 'before', 'sameGen 只在 measure 调用时成立：布局趟如果命中缓存就会跳过子节点定位（STEP 5），把子节点留在上一次的位置上；measure 调用只关心宽高，缓存里正好有'),
    (1105, 'before', '多槽缓存扫描逐个比对 8 个输入字段，命中就恢复该槽存下的宽高。这一段是滚动性能的关键：500 条消息加一个脏叶子，脏叶重排从 7.6 万次 layoutNode 调用（21.7 倍节点数）降到 4 千次（1.2 倍），6.86ms 降到 550µs'),
    (1123, 'after', '用 sameFloat 而不是 === 比对四个尺寸，是为了让 NaN 与 NaN 视为相等——未定义尺寸的节点也能命中'),
    (1152, 'before', '缓存输入必须提前提交，让每一个 return 路径都留下合法条目。更关键的是 isDirty_ 只在布局趟清除，原因见下一条'),
    (1160, 'before', 'wasDirty 决定后续的缓存失效策略：布局趟清 isDirty_ 并作废 measure 槽；measure 趟不清 isDirty_ 但要作废脏节点的 layout 槽'),
    (1172, 'after_block', '以前这里会清空 _cN 来防止改动前的旧条目命中（曾导致长时间连续黑屏），后来改成代际戳：缓存检查要求「同代际或节点干净」，所以脏节点上一代的条目本来就进不来；继续清空反而会抹掉本轮 measure 调用刚写进去的新条目'),
    (1187, 'after_block', 'measure 趟不能清 isDirty_ 的原因：同一趟 calculateLayout 里，measure 在前、layout 在后，如果在 measure 阶段就清了脏，后面的 layout 趟会命中上一次布局留下的旧缓存（那时子节点还没插入），于是 ScrollBox 的内容高度永远不增长、粘性滚动永远跟不上新内容'),
    (1201, 'before', '三个边数组都是原地解析，直接写进预分配的 layout 数组——省掉每次 layoutNode 三次数组分配与十二次 resolveEdge 调用（这曾是 CPU 剖析的第一热点）。没设置过任何边时直接写四个零，比走解析函数更便宜'),
    (1211, 'before', 'padding 与 border 合起来算内框偏移：主轴/交叉轴各一个。这两个数字后面反复出现，所以提前算好'),
    (1215, 'before', '样式里显式写了尺寸就覆盖传入的可用尺寸，并把模式强制成 Exactly——这就是「父容器的建议不如子节点自己的声明」'),
    (1235, 'before', 'min/max 约束在这里统一施加，包括百分比形式；boundAxis 内部有「未设置 min/max」的快速路径，因为这是绝大多数情况'),
    (1239, 'before', 'measure-func 叶子：有测量函数且没有子节点。这是文本节点的分支，它不跑 flexbox，直接把约束交给回调'),
    (1248, 'before', '传给测量函数的是扣除内边距与边框后的内框尺寸；模式为 Undefined 时对应轴传 NaN，表示「没有约束，按内容来」'),
    (1250, 'before', 'Exactly 模式直接用给定尺寸（不采信回调结果），否则把回调测出的内容尺寸加回内边距，再过一次 min/max 夹紧——加回内边距这一步很容易漏，漏了就会让带 padding 的文本节点每次少算两个 padding'),
    (1271, 'before', '脏节点也写缓存：虚拟滚动新挂载的项第一次布局是脏的，但脏链的测量/布局级联会在同一趟里调它很多次，写着缓存让第 2 次起就能命中（布局趟已经把 isDirty_ 清了）。实测 1593 个节点的全新挂载树从 10.5 万次访问降到 1 万次'),
    (1292, 'before', '无子节点也没有测量函数的叶子：尺寸就是内边距加边框（内容为空），除非有 Exactly 约束或样式尺寸'),
    (1322, 'before', '进入容器分支：先按 flex-direction 拆出主轴与交叉轴，把「宽高」这套物理概念换成「主轴尺寸/交叉轴尺寸」，后面整段算法就与方向无关了'),
    (1334, 'before', '内框主轴/交叉尺寸要扣掉对应的内边距边框；尺寸不定时保持 NaN，让下游一路用 isDefined 判断，而不是塞一个假值'),
    (1342, 'before', '主轴方向的 gap 取哪个槽取决于主轴是否水平：水平主轴用 column-gap（列与列之间），垂直主轴用 row-gap。这里最容易写反'),
    (1348, 'before', '子节点分两类：参与流式布局的与绝对定位的。display:contents 的节点在这一步就被拍平——它自己的盒子被移除，子节点递归提升到祖父的列表里'),
    (1356, 'before', '子节点百分比以本节点的内容盒为准：本节点宽度不定时，子节点的百分比宽度也不定，绝不能退到祖父的尺寸上——这是 CSS 里一条常被实现错的规则'),
    (1368, 'before', 'STEP 1：先给每个流式子节点算 flex-basis（它在主轴上的理想尺寸），再决定怎么换行。basis 的算法单独一个函数，因为有四级回退：显式 basis → 主轴样式尺寸 → 实测 → 0'),
    (1383, 'before', '不换行容器、或者主轴尺寸不定（无法判断何时该换）、或者没有子节点时，恒为一行——尺寸不定时按一排无限长处理'),
    (1387, 'before', '换行判定用的是「假设主轴尺寸」而不是原始 basis：规范第 9.3.5 节要求先按 min/max 夹紧再判是否超出行宽，直接用 basis 会让带 max-width 的项提前换行'),
    (1408, 'before', '基线布局只在 row 方向成立（垂直排布谈基线没有意义），且需要容器 align-items 为 baseline 或任一子节点 align-self 为 baseline；提前算一次，避免在两层循环里反复判断'),
    (1412, 'before', '三张每行账本：主轴消耗量、交叉尺寸、基线布局时还要记最大 ascent。都用普通数组，行数通常小于 10，不值得上 TypedArray'),
    (1419, 'before', '逐行处理：先算出这一行所有 basis 加 margin 加 gap 的总和，作为弹性分配的起点'),
    (1426, 'before', '容器主轴尺寸不定但有 min/max 时，先按「内容自然长度」与 min/max 的关系推一个可用主轴——内容超上限就用上限，不到下限就用下限，否则保持不定'),
    (1454, 'before', '本行内逐个测交叉尺寸：先看样式有没有显式交叉尺寸，再看是否单行 stretch，最后退到「不超过内框交叉尺寸」。三种情形的模式分别是 Exactly、Exactly、AtMost，差一个都会让子节点算错'),
    (1473, 'after_block', '多行换行时刻意用 Undefined 模式测内在交叉尺寸，而不是直接拉伸到容器：行高必须先由内容定下来，再让行内各项重新拉伸——否则行内带 flex-grow 的孙节点会先把行撑满整个容器，行高失去意义'),
    (1507, 'before', '记下子节点实际拿到的交叉尺寸，行高取本行所有子节点（含交叉边距）的最大值'),
    (1512, 'before', '基线布局的行高还要单独抬一次：必须容纳本行内基线对齐项的最大 ascent + descent。这一步只对 row 方向有意义'),
    (1529, 'before', '直接读子节点算好的 layout.margin 而不再走 childMarginForAxis 重新解析——同一个 ownerW 下结果必然相同，重复解析纯粹浪费（每个子节点省两次 resolveEdge）'),
    (1547, 'before', 'STEP 4 定容器自身尺寸。这里有三种输入模式与两种溢出策略的组合，写成分层三目而不是 if 链，是为了让「Exactly 优先、Scroll 才钳制、否则按内容」这条优先级一眼可见'),
    (1553, 'before', '关键语义：AtMost（fit-content）不是硬上限，内容可以溢出；只有 overflow:scroll 才把尺寸钳到可用范围内。这一条区分了「建议尺寸」与「必须尺寸」'),
    (1560, 'after', '多行换行且模式为 AtMost 时直接采用可用主轴——因为换行就是在这个边界上发生的，此时内容总长必然超过可用值，按内容算会算出比可用值还大的容器'),
    (1570, 'before', '最终尺寸仍要过一遍 min/max 夹紧：内容算出来的尺寸可能违反自身声明的约束，这一步是兜底'),
    (1599, 'before', 'measure 趟到此为止：尺寸已定并写入缓存，但不再往下走定位。这是「测量」与「布局」两趟分离的分界点，也是缓存能分两套的原因'),
    (1601, 'before', 'STEP 5 定位：先用最终尺寸倒推实际内框（可能与计算过程中用的内框不同，因为 min/max 夹紧改变了尺寸），再逐行摆子节点'),
    (1620, 'before', 'align-content 的剩余交叉空间：单行不换行且非基线时直接让那一行占满整个内框交叉尺寸（行内对齐交给 align-items），否则按六种取值分配'),
    (1660, 'before', 'wrap-reverse 不改变行的生成顺序，而是在算交叉坐标时翻转：行的逻辑位置从交叉轴尾部开始堆叠。这样换行算法本身不用关心方向'),
    (1671, 'before', '行高确定后重新拉伸一次：多行换行时初始测量不知道行高，单行且容器交叉尺寸不是 Exactly 时初始拉伸也被跳过了。两处都必须在这里补上'),
    (1691, 'after_block', '重新拉伸的三个前提：对齐方式是 stretch、子节点没有显式交叉尺寸、没有交叉方向的 auto margin。任一不满足就不能动——尤其 auto margin 会把剩余空间吃掉，拉伸就没有意义'),
    (1719, 'before', 'justify-content 与 auto margin 是同一条主轴分配逻辑的两条分支：数出本行有多少个 auto margin，有就由它们瓜分剩余空间，没有才走 justify-content'),
    (1730, 'before', 'auto margin 优先于 justify-content——这是 CSS 的明确规定。每个 auto margin 分到的空间必须在所有 auto margin 之间均分，而不是每项均分'),
    (1762, 'before', '计算实际交叉位置：wrap-reverse 时用「容器交叉尺寸减逻辑位置减本行尺寸」翻转，其余情况直接用逻辑位置'),
    (1804, 'before', '反向主轴从容器尾部倒推：位置从主轴起点累加，但落位时用「容器尺寸减起点位置减自身尺寸」。累加方向不变，只是落位镜像'),
    (1810, 'before', '交叉对齐先算剩余空间，再按四种情形处理：两侧都 auto 则居中、仅前 auto 则靠后、仅后 auto 则保持靠前（注释里写「stays at leading」）、都没有才看 align'),
    (1830, 'before', '基线对齐：子节点的 baseline 要对齐到本行的最大 ascent，所以它的顶部位置等于行起点加最大 ascent 减自身 baseline。只有 row 方向会进来'),
    (1848, 'before', '相对定位偏移：同时给了 left 和 right 时以 left 为准，只给 right 时取负值。整段被 _hasPosition 包裹，没设过内缩值的节点不付这四次解析的代价'),
    (1879, 'before', '主轴与交叉轴的结果按方向落回物理 left/top：水平主轴时主轴结果进 left、交叉结果进 top，垂直主轴时反过来。整段算法与方向无关的关键就在这一次交换'),
    (1886, 'before', '推进主轴游标：加上自身主轴尺寸、两端外边距、以及项间距。betweenMain 在 justify-content 分配后已经含了额外间距'),
    (1891, 'before', 'STEP 6 绝对定位子节点：它们不参与流式布局，所以在所有流式子节点定位完之后单独处理'),
    (1904, 'before', 'layoutAbsoluteChild 处理绝对定位：先解析四个方向的内缩值（百分比以父的尺寸为基准），再解尺寸，然后布局子节点，最后按「有内缩用内缩、没内缩用对齐」定位'),
    (1923, 'before', '绝对定位子节点的百分比尺寸以父的 padding-box 为基准（父尺寸减边框），这是 CSS 第 10.1 节的规定；用父的 content-box 会差一个 padding'),
    (1930, 'before', '左右内缩都给了但没给宽度时反推宽度：可用宽度减左右内缩。这是绝对定位的经典用法「撑满两侧」'),
    (1949, 'before', '外边距在定位之后还要再叠加一次：内缩值决定的是盒子的边缘位置，外边距把盒子往里推。两者是相加关系'),
    (1963, 'before', 'left 的五个分支按优先级：有左内缩用左内缩、有右内缩从右边倒推、主轴水平时走 justify-content、主轴垂直时走交叉对齐。方向不同走的是完全不同的分配函数'),
    (1992, 'before', 'top 的五个分支与 left 完全镜像：主轴垂直时走 justify-content，主轴水平时走交叉对齐。两段代码几乎对称，但合并会引入方向判断，反而更慢'),
    (2023, 'before', 'justifyAbsolute 只处理三种情形：居中、靠尾、其余（含 space-* 全部退化为靠头）。绝对定位的单项没有「之间」的概念，空间分布类取值全部无意义'),
    (2039, 'before', 'alignAbsolute 在 wrap-reverse 下把 flex-start 与 flex-end 互换：反转换行改变了交叉轴的物理方向，但绝对定位的子节点不该跟着换，所以这里主动抵消'),
    (2059, 'before', 'computeFlexBasis 决定子节点在主轴上想要多大。四级回退的顺序就是规范规定的顺序：显式 basis → 主轴样式尺寸 → 交给子节点自己测 → 0'),
    (2090, 'before', '显式 flex-basis 权重最高，负值按零处理；算完立刻写六字段缓存并盖代际戳，后续同一趟内的重复调用直接命中'),
    (2104, 'before', '没有显式 basis 就看主轴方向的样式尺寸（row 看 width、column 看 height），这一层不需要递归'),
    (2120, 'before', '两层都没有就必须实测：把交叉轴方向的约束准备好，再递归调一次 layoutNode（performLayout=false，纯测量）'),
    (2135, 'before', '上游 YGNodeComputeFlexBasisForChild 在子树里有测量函数时，会把可用主轴以 AtMost 传下去——否则文本节点会报出不受约束的自然宽度作为 basis，把兄弟节点挤扁、并在错误的宽度处换行。Ink 曾经就是这里的 <Text> 在 flexGrow 容器里宽度取成内在宽度，换行边界掉字符'),
    (2150, 'before', '这个约束有两个限制条件：只管宽度（高度一旦被约束，可滚动内容就溢不出来，ScrollBox 会被裁掉），且只对含测量函数的子树生效（纯布局子树的 flexGrow 子节点会顺着 AtMost 长满，把 basis 撑大，破坏 flex_grow_in_at_most 这类规范的测试）'),
    (2162, 'before', '注意这次递归传的是 performLayout=false：只测尺寸、不做定位。basis 计算阶段反正是要重排的，这里定位纯属浪费'),
    (2174, 'before', 'hasMeasureFuncInSubtree 是上面那条规则的判据：子树里只要有一个测量函数就要按文本容器的规则处理。递归没做记忆化，因为子树深度通常很小'),
    (2182, 'before', 'resolveFlexibleLengths 实现规范第 9.7 节「解析弹性长度」：分配剩余空间、检测 min/max 违例、冻结所有违例项、在未冻结项之间重新分配，反复直到稳定'),
    (2198, 'before', '第一轮先冻结不参与伸缩的项：主轴尺寸不定（没得分配）、或者剩余空间为正但 flexGrow 为 0、或者剩余为负但 flexShrink 为 0。冻结项直接取夹紧后的 basis'),
    (2212, 'before', '迭代分配，最多 n+1 轮（每轮至少冻结一个，必然收敛）：每轮重算「初始剩余空间减去已冻结项相对 basis 的增量」，这才是规范要求的做法——静态地减一次会在多轮冻结后算错'),
    (2233, 'before', '规范第 9.7 节第 4c 步：flex 因子之和小于 1 时只分配「初始剩余空间乘以因子和」而不是全部剩余空间，这样 flex:0.5 的项真的只吃一半空间'),
    (2268, 'before', '按违例符号冻结：总违例为正（有项撞了下限）就冻结所有撞下限的，为负（撞上限）就冻结撞上限的。冻结后进入下一轮重新分配——这就是多趟夹紧的实质'),
    (2284, 'before', 'isStretchAlign 只用于判断「basis 测量时交叉轴该用 Exactly 还是 AtMost」：拉伸对齐的项可以按容器尺寸硬测，其余只能给上限'),
    (2294, 'before', 'resolveChildAlign 把 align-self 为 Auto 的节点回退到父的 align-items。全文件有多处需要这条回退，抽出来避免每处各写一遍三目'),
    (2300, 'before', 'calculateBaseline 按 CSS 第 8.5 节实现：叶子节点用自己的高度当基线；容器递归进第一个基线对齐的子节点（没有基线对齐项就取第一个流式子节点），返回它的基线加上它的 top 偏移'),
    (2307, 'after', '只看第一行的子节点：`c._lineIndex > 0` 就 break，因为多行容器的基线由第一行决定，后面的行不参与'),
    (2325, 'before', 'isBaselineLayout 提前判定整个容器是否需要基线布局：必须 row 方向，且容器或某个流式子节点声明了 baseline。提前算一次避免在逐行循环里重复判断'),
    (2334, 'before', 'childMarginForAxis 返回子节点在某轴两端的边距之和；没有设置过任何 margin（_hasMargin 为 false）时直接返回 0，省掉两次边解析'),
    (2345, 'before', 'resolveGap 先看具体方向的槽，未定义再回退到 all 槽；负值夹到零——gap 为负在 CSS 里无效'),
    (2352, 'before', 'boundAxis 施加 min/max 约束。注意 max 先于 min 施加：当 min 大于 max 时以 min 为准，这是 CSS 的规定'),
    (2363, 'before', '快速路径：两个约束都没设置时原样返回。1000 节点基准上每趟约 3.2 万次调用，几乎全部走这条路径，省掉的是两次 resolveValue 加两次 isNaN'),
    (2370, 'after_block', '内联了 resolveValue 的两个分支并用 `m === m` 代替 !isNaN：这段是纯热点优化，语义与调用函数完全等价'),
    (2386, 'before', 'zeroLayoutRecursive 把子树全部尺寸与位置清零，用于 display:none 的隐藏节点与 display:contents 的盒子'),
    (2392, 'before', '清零的同时必须标脏并作废单槽缓存：否则从隐藏改回可见时，calculateLayout 会发现这个子节点是干净的、_hasL 完好，于是在缓存处提前返回，跳过子节点定位递归——孙节点还停在上面的全零状态，渲染出来是隐形的。标脏同时也让 _cN 与 _fbBasis 因为「同代际或干净」的条件而不命中'),
    (2406, 'before', 'collectLayoutChildren 把子节点分成流式与绝对定位两类，并把 display:contents 的子树拍平：这种节点的盒子被移除，但它的子节点保留并提升到祖父的列表里，递归处理多层嵌套'),
    (2427, 'after_block', '注意三类判定有先后顺序：先判 display（none 与 contents 都优先），再判定位方式。一个 display:contents 且绝对定位的节点会被当作 contents 拍平，而不是当绝对定位项——这个优先级与 CSS 一致'),
    (2435, 'before', 'roundLayout 做像素网格舍入：scale 为 0 表示关闭舍入。整棵树自顶向下传绝对坐标，原因是宽高要用「绝对右下角减绝对左上角」算，避免逐层舍入累积漂移'),
    (2451, 'before', '文本节点与非文本节点舍入方式不同（对齐上游 PixelGrid.cpp）：文本的位置向下取整，保证换行的文字绝不会从分配到的列之后再开始；宽度用「有小数就向上取整」，避免裁掉最后一个字形。其余节点走标准四舍五入——不加这个区分的话，justify 居中与 space-evenly 的位置会与 WASM 版差一个字符格，flex-shrink 溢出时兄弟节点会落到错误的列'),
    (2461, 'before', '宽高不是直接舍入，而是先算绝对右下角、舍入后再减去舍入后的左上角。这样同一行相邻两个盒子共享一条边时不会出现一像素缝隙或重叠'),
    (2478, 'before', 'isWholeNumber 用 1e-4 的容差判断是否「已经是整数」，而不是严格比较——浮点乘法后 3 会变成 2.9999999996，严格比较会把整数误判成小数'),
    (2483, 'before', 'roundValue 是像素舍入的原子操作：先乘 scale，取小数部分，再用 1e-4 容差对齐上游的 YGDoubleEqual；命中容差就当整数处理，否则才看是否需要强制向上或向下'),
    (2503, 'before', '默认分支用的是「大于等于 0.4999 就进位」而不是 0.5：这是为了吃掉浮点误差，让 0.4999999 这种本该进位的情况不至于掉下去'),
    (2511, 'before', 'parseDimension 是字符串/数字到 Value 的唯一转换点：undefined 给未定义、字符串 auto 给 auto、数字给点值、百分号结尾给百分比、其余按数字解析，失败则未定义'),
    (2515, 'before', 'NaN 与正负无穷都当未定义。这一条不是防御性代码而是实际需求：Ink 会传 height={Infinity} 表示不限制（LogSelector 的 maxHeight 默认值就是这样），存成字面点值会让节点高度变成无穷并摧毁下游所有布局'),
    (2528, 'before', 'physicalEdge 把 9 个逻辑边映射到 4 个物理边：Start 归 Left、End 归 Right（LTR 前提），default 也归 Left——getComputedBorder 这类读取 API 传进奇怪值时不会崩，只是取到左边的值'),
    (2548, 'before', 'Yoga 类型就是上游 yoga-layout/load 的模块形状：Config 与 Node 各带 create/destroy。三个 create 变体（无参、默认、带 config）都要有，因为上游历史上换过推荐写法'),
    (2561, 'before', '单例对象把上面所有工厂函数挂上去；destroy 全为空实现——JS 有 GC，这里只需要语义上的释放'),
    (2574, 'before', 'loadYoga 返回已解析的 Promise 而不是真正的异步加载：上游 WASM 版需要 await 初始化，改成纯 TS 后为了不改调用方代码，保留这个签名直接 resolve'),
]
